mapper.select:
SELECT , CAST(ROUND( ( SELECT COALESCE(SUM(sd2.weight), 0) FROM song_descriptor sd2 WHERE sd2.song_id = pw.id AND sd2.descriptor_id IN
#{descriptorId}
) / #{descriptorCount}, 4 ) AS DECIMAL(5,4)) AS match_score FROM playable_work pw JOIN song s ON s.work_id = pw.id WHERE AND EXISTS ( SELECT 1 FROM song_descriptor matched WHERE matched.song_id = pw.id AND matched.descriptor_id IN
#{descriptorId}
) ORDER BY match_score DESC, pw.updated_at DESC, pw.id DESC LIMIT #{limit}

SELECT COUNT(*)
FROM digital_asset
WHERE id = #{assetId}

SELECT id
FROM experience_session
WHERE session_token = #{sessionToken}

mapper.update:
UPDATE discovery_candidate
SET selected_at = CURRENT_TIMESTAMP(3)
WHERE request_id = #{requestId}
  AND song_id = #{songId}
  AND selected_at IS NULL

mapper.select:
SELECT id
FROM performance_feedback
WHERE performance_run_id = #{performanceId}

mapper.insert:
INSERT INTO performance_feedback (
    performance_run_id,
    rating,
    comment_text
) VALUES (
    #{performanceRunId},
    #{rating},
    #{commentText}
)
